def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_def = sum(1 for a in op if a == 'D')
    my_def = sum(1 for a in my if a == 'D')
    last_op = op[-1]
    last_me = my[-1]

    # Defection streak by opponent
    streak = 0
    for a in reversed(op):
        if a == 'D':
            streak += 1
        else:
            break

    # Cooperation streak by opponent
    cstreak = 0
    for a in reversed(op):
        if a == 'C':
            cstreak += 1
        else:
            break

    # Fully cooperative opponent
    if op_def == 0:
        if n >= 99:
            return 'D'
        if n >= 97 and cstreak >= 20:
            return 'D'
        return 'C'

    # Mostly cooperative opponent: reciprocal with light retaliation
    if op_def <= 2:
        if last_op == 'D':
            return 'D'
        if n >= 98:
            return 'D'
        return 'C'

    # Persistent defector: punish, but try occasional restart
    if streak >= 3:
        if rng.random() < 0.08 and n < 95:
            return 'C'
        return 'D'

    # If opponent has been heavily defecting overall
    if op_def * 3 > n * 2:
        if rng.random() < 0.05 and n < 90:
            return 'C'
        return 'D'

    # Recovering cooperator: after long CC streak try one probe
    if last_op == 'C':
        if cstreak >= 12 and n < 85 and rng.random() < 0.06:
            return 'D'
        if my_def > op_def + 2:
            return 'C'
        return 'C'

    # last_op == 'D' (isolated or moderate)
    if streak == 1:
        # Forgive isolated defection if opponent has been decent
        if op_def * 4 <= n and rng.random() < 0.4:
            return 'C'
        return 'D'

    # streak == 2
    if rng.random() < 0.15 and n < 95:
        return 'C'
    return 'D'
